E("mp-ladli-behna-yojana", name="Mukhyamantri Ladli Behna Yojana (Madhya Pradesh)", short="₹1,500 a month for eligible women of Madhya Pradesh. New registrations are reported to be closed for now.", tag="MP · Women", ministry="Women & Child Development Department, Madhya Pradesh",
 facts=[("Monthly amount","₹1,500 (from Nov 2025, earlier ₹1,250)"),("Beneficiaries","About 1.25 crore women"),("Family income limit","₹2.5 lakh a year"),("Helpline","0755-2700800")],
 about="Ladli Behna is a Madhya Pradesh Government scheme that sends direct financial help (DBT) to the bank accounts of eligible women every month. It started in 2023 at ₹1,000 and is now ₹1,500 a month. Payment status can be checked on cmladlibahna.mp.gov.in.",
 benefits=["₹1,500 a month directly into the bank account (from November 2025)","The 41st instalment was released on 14 October 2026 to about 1.25 crore women","The amount has changed from time to time as announced by the government"],
 elig=["Woman who is a permanent resident of Madhya Pradesh","Annual family income up to ₹2.5 lakh","Age and other conditions as per scheme rules (generally said to be 23 to 60 years, confirm on the portal)","Aadhaar-linked bank account active for DBT, and Samagra ID"],
 notelig=["Beneficiaries are removed from the list on turning 60","Those who do not meet the conditions or have passed away","As per reports, new registrations are closed for now and no timeline for reopening has been given"],
 docs=["Aadhaar card","Samagra ID","Aadhaar-linked bank account","Residence proof","Income information (where asked)"],
 steps=["Open cmladlibahna.mp.gov.in","To check payment status, enter application number or Samagra member ID, captcha and OTP","Ask on the portal or at your ward/panchayat office whether new applications are open","If you have a problem, call helpline 0755-2700800"],
 link_label="cmladlibahna.mp.gov.in – official portal", helpline="Helpline: 0755-2700800",
 faq=[("How much does Ladli Behna give now?","₹1,500 a month, raised from ₹1,250 in November 2025."),("Can new applications be made?","As per reports new registrations are closed for now with no reopening date given. Check the latest status on the portal."),("Will the amount become ₹3,000?","An increase to ₹3,000 has been mentioned as a political promise but there is no official timeline.")],
 note="The age limit and the rest of the eligibility could not be fully verified for this page. The status of new registrations can change, so confirm with the portal/helpline.")
